window.FIRST_CHANNEL = [{"id": 929, "slug": "first-929", "title": "What is sent is not what is received!", "fullTitle": "What is sent is not what is received!", "date": "2024-10-26", "lang": "en", "tags": [], "body": "", "excerpt": "", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/929"}, {"id": 925, "slug": "first-925", "title": "What is it you want to do with your life?", "fullTitle": "What is it you want to do with your life?", "date": "2024-09-29", "lang": "en", "tags": ["question"], "body": "***<br><br>Every decision you make should be in service of that&#33;", "excerpt": "*** Every decision you make should be in service of that!", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/925"}, {"id": 913, "slug": "first-913", "title": "Which one is more important: Destination or Journey?", "fullTitle": "Which one is more important: Destination or Journey?", "date": "2024-05-04", "lang": "en", "tags": ["keepinmind"], "body": "- It&#39;s your <b>Partner</b> in the Journey to the Destination", "excerpt": "- It's your Partner in the Journey to the Destination", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/913"}, {"id": 911, "slug": "first-911", "title": "O'tgan har bir kunim - dars, uchratgan har bir insonim muallimdir.", "fullTitle": "O'tgan har bir kunim - dars, uchratgan har bir insonim muallimdir.", "date": "2024-04-28", "lang": "uz", "tags": ["hayot_haqiqati", "òylantirib_qòydi"], "body": "Qaysi tomonga ketsang ketaver, yo&#39;l oxirida yana o&#39;zing bilan uchrashasan", "excerpt": "Qaysi tomonga ketsang ketaver, yo'l oxirida yana o'zing bilan uchrashasan", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/911"}, {"id": 885, "slug": "first-885", "title": "Bir rohib aytgan ekan: \"Jahl - bu boshqa bir insonning qilgan xatosi…", "fullTitle": "Bir rohib aytgan ekan: \"Jahl - bu boshqa bir insonning qilgan xatosi uchun biz o'zimizga beradigan jazoyimiz\"", "date": "2023-11-14", "lang": "uz", "tags": ["wisdom", "anger", "calmness"], "body": "Kimdir noto&#39;g&#39;ri ish qiladi, kech qoladi, aytgan ishingizni qilmaydi, xabaringizni o&#39;qiydi - javob qaytarmaydi... va hokozo.<br><br>O&#39;sha payt jahl qilishiz, siqilishiz qanchalik to&#39;g&#39;ri???<br><br>Xato qilgan siz emas. Siz noto&#39;g&#39;ri ish qimadiz, siz kech qolmadiz, aytilgan ishni qilmagan siz emas - shuning uchun jahl qilmang.<br><br>Jazoni aybdorga qoldiring&#33;", "excerpt": "Kimdir noto'g'ri ish qiladi, kech qoladi, aytgan ishingizni qilmaydi, xabaringizni o'qiydi - javob qaytarmaydi... va hokozo. O'sha payt jahl…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/885"}, {"id": 848, "slug": "first-848", "title": "Bu men uchun hech nimani anglatmaydi!", "fullTitle": "Bu men uchun hech nimani anglatmaydi!", "date": "2023-08-15", "lang": "uz", "tags": [], "body": "Messidan bir kun 30 yoshga kirganda muhbir so&#39;riydi:<br>- Mana siz futbolchisiz, mashhur futbolchisiz, yoshizam 30ga kiribdi... Bu siz uchun nimani anglatadi? Nimani his qivos? - dib so&#39;riydi muhbir.<br><br>Messi javob beradi:<br>- Hich nima&#33; Mani yoshimi 30ga kirganini anglatadi.<br><br>Yuzaki javobga o&#39;xshiydi, lekin aslida judayam chuqur ma&#39;noli javob.", "excerpt": "Messidan bir kun 30 yoshga kirganda muhbir so'riydi: - Mana siz futbolchisiz, mashhur futbolchisiz, yoshizam 30ga kiribdi... Bu siz uchun nimani…", "minutes": 1, "media": "video", "url": "https://t.me/mrshokh_first/848"}, {"id": 806, "slug": "first-806", "title": "Baxt - bu moment emas!", "fullTitle": "Baxt - bu moment emas!", "date": "2023-04-21", "lang": "uz", "tags": ["realization"], "body": "Ya’ni siz nimagadur erishgan paytizdagi hursandchilikni baxt dib aytolmaysiz…<br><br><b>Baxt - bu jarayon&#33; </b><br>O’sha hursandchilikni qanchalik davom etishi - baxt<br><br>Inson baxtli yoki baxtsiz bo’lishini natijaga bog’lab qo’yishi xato…<br><br>Jarayonni o’zidan mazza qilayotgan bo’lsez mana shu haqiqiy baxt. <br><br>Agar natijani kutib, qachonki shunaqa bo’sa kiyin baxtli bo’laman dib yurgan bo’sez - kotta ehtimol bilan xato yo’ldasiz&#33;<br><br>Maqsadiz xato digani emas bu - shunchaki maqsad tomon ketayotgan yo’lizdan yurayotganizi o’zi hursand qimayaptimi sizni? <br><br>Demak: Yo’lni o’zgartirish kerak<br><br>P.s: <i>kitoblardan o’qilgan ma’lumotlar + podcastdan olingan insight lar = yangi shaxsiy fikr</i>", "excerpt": "Ya’ni siz nimagadur erishgan paytizdagi hursandchilikni baxt dib aytolmaysiz… Baxt - bu jarayon! O’sha hursandchilikni qanchalik davom etishi - baxt…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/806"}, {"id": 747, "slug": "first-747", "title": "2 yil", "fullTitle": "2 yil", "date": "2023-03-09", "lang": "uz", "tags": [], "body": "Blogni ochganimga roppa rosa 2yil bo’pti bugun…<br><br>2021-yil 9-martda ochgan ekanman kanalni…<br><br>Bu vaqt mobaynida ancha o’zgarishlar bo’ldi&#33;<br><br>Kanalni boshidan boshlab o’qib kelinsa, farq seziladi…<br><br>O’zim sezdim har holda, o’zimga bilindi&#33;<i></i>", "excerpt": "Blogni ochganimga roppa rosa 2yil bo’pti bugun… 2021-yil 9-martda ochgan ekanman kanalni… Bu vaqt mobaynida ancha o’zgarishlar bo’ldi! Kanalni…", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/747"}, {"id": 681, "slug": "first-681", "title": "Izlagan imkon topar…", "fullTitle": "Izlagan imkon topar…", "date": "2023-02-19", "lang": "uz", "tags": [], "body": "Bizni biror ishni qilish yoki qilmasligimiz o’z qo’limizda… <br><br>Lekin qila olamizmi yoki yo’q…<br><br><b>Hammasi borib hoxishlarimizga taqaladi&#33; </b><br><br>Ya’ni inson o’zi qattiq hoxlagan narsasini albatta qiladi, qilishga imkon topadi.<br><br>Hoxlamagan paytda bahonalardan foydalanadi…<br><br><b>Hoxlagan odam izlaydi…<br>Izlagan - topadi&#33;&#33;&#33;</b><br><br>Vaqtim yo’, charchab keldim o’zi…<br>Manam odamman, manam xato qilaman, bandamizku hammamizam diymizda ertalab bomdodga uxlab qolamiz… <br><br><i>Balki Jannatga kirishni ich-ichimizdan qattiq xohlamasmiz?&#33;</i>", "excerpt": "Bizni biror ishni qilish yoki qilmasligimiz o’z qo’limizda… Lekin qila olamizmi yoki yo’q… Hammasi borib hoxishlarimizga taqaladi! Ya’ni inson o’zi…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/681"}, {"id": 649, "slug": "first-649", "title": "O’zgarish haqiqiy bo’lsa - avvalgi holatga boshqa qaytilmaydi", "fullTitle": "O’zgarish haqiqiy bo’lsa - avvalgi holatga boshqa qaytilmaydi", "date": "2023-02-11", "lang": "uz", "tags": ["reality"], "body": "Xatolar qildim… xulosalar oldim degan inson boshqa qaytib bunday xatoga yo’l qo’ymaydi, agarda yana xuddi o’sha xatoni takrorlayotgan bo’lsa, demak avvalgisidan to’g’ri xulosa chiqarmagan&#33;&#33;&#33;", "excerpt": "Xatolar qildim… xulosalar oldim degan inson boshqa qaytib bunday xatoga yo’l qo’ymaydi, agarda yana xuddi o’sha xatoni takrorlayotgan bo’lsa, demak…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/649"}, {"id": 641, "slug": "first-641", "title": "Ba’zida (turli sabablarga ko’ra) uzoqlashishga majbur bo’lasiz…", "fullTitle": "Ba’zida (turli sabablarga ko’ra) uzoqlashishga majbur bo’lasiz:", "date": "2023-02-08", "lang": "uz", "tags": ["realization"], "body": "- Ota-onadan <br>- Yoru-do’stlardan<br>- O’ziz katta bo’lgan mahalladan<br>- Shahardan, davlatdan…<br><br>Ha bu ayriliq sizni jismonan yiroqlashtirishi mumkin. <b>Lekin, ishoning: qalban juda yaqinlashtiradi&#33;&#33;&#33;</b><br><br>P.s: <i>hammasi yaxshilikka :)</i>", "excerpt": "- Ota-onadan - Yoru-do’stlardan - O’ziz katta bo’lgan mahalladan - Shahardan, davlatdan… Ha bu ayriliq sizni jismonan yiroqlashtirishi mumkin. Lekin…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/641"}, {"id": 635, "slug": "first-635", "title": "Ba’zan hammasiga qo’l siltab ketgin keladiyuu…", "fullTitle": "Ba’zan hammasiga qo’l siltab ketgin keladiyuu…", "date": "2023-02-07", "lang": "uz", "tags": ["realization"], "body": "- Shartta ishdan bo’shab ketvorishni xohlesan…<br>- Shartta uyingga, ota-onangni oldilariga qaytvormoqchi bo’lasan…<br>- Birdan hech narsa qilgin kelmay qoladi…<br>- Har kimdan va har narsadan uzoqlashishni xohlab qolasan kishi…<br><br>Lekin: ich-ichingda nimadur bunday qilishga yo’l qo’ymaydi&#33;<br><br>Aynan o’sha narsa: <br><br>Nima sodir bo’lsa ham, qanday vaziyatga tushganingdan qat’iy nazar sabr ila faqat oldingi qadam tashlashga undayveradi&#33;<br><br>P.s:<i> u narsa nimaligini anniq bilmiman, balki umiddur… yoki yelkadagi mas’uliyat, balki qalbdagi muhabbatdur…<br><br>Nima bo’lsa ham, toki u bor ekan, ortga qadam tashlash varianti yo’q bo’ladi&#33;</i>", "excerpt": "- Shartta ishdan bo’shab ketvorishni xohlesan… - Shartta uyingga, ota-onangni oldilariga qaytvormoqchi bo’lasan… - Birdan hech narsa qilgin kelmay…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/635"}, {"id": 616, "slug": "first-616", "title": "Bog'bon bo'lish oson emas...", "fullTitle": "Bog'bon bo'lish oson emas...", "date": "2023-02-04", "lang": "uz", "tags": [], "body": "Shunchaki&nbsp; bog&#39;da ishlash, 3-4 ta gul ekish va kun ora tagiga suv quyib turish bilan har kim ham bog&#39;bon bo&#39;lib qolavermaydi...<br><br>Bog&#39;bonning o&#39;ziga xos yana ko&#39;plab xislatlari bo&#39;ladi: <br><br>Haqiqiy bog&#39;bonning ich-ichidan bog&#39;dorchilikka qiziqishi va ishtiyoqi bo&#39;ladi<br><br>Hamisha eng yaxshi bog&#39;bon bo&#39;lishga intiladi va shu sohada yangiliklarga o&#39;ch bo&#39;ladi, tinimsiz o&#39;rganadi<br><br>Har bir gul ko&#39;chatiga alohida ahamiyat beradi va shunga ko&#39;ra parvarishlaydi... <br><br>Har birini kerakli miqdorda sug&#39;oradi... <br><br>Gullarni o&#39;stirib, ko&#39;rsa ko&#39;zni quvontiradigan qilib tarbiya qiladi...<br><br>Va eng muhimi haqiqiy bog&#39;bon bog&#39;idagi barcha o&#39;simlik va gullarni barini birdek - o&#39;z oilasidek ko’radi&#33;<br><br>P.s: <i>bog&#39;bon = o&#39;qituvchi, ustoz)</i>", "excerpt": "Shunchaki bog'da ishlash, 3-4 ta gul ekish va kun ora tagiga suv quyib turish bilan har kim ham bog'bon bo'lib qolavermaydi... Bog'bonning o'ziga xos…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/616"}, {"id": 615, "slug": "first-615", "title": "Agar yomg’ir: havodagi chang-g’uborni ketkazgani kabi gunohlarni ham…", "fullTitle": "Agar yomg’ir: havodagi chang-g’uborni ketkazgani kabi gunohlarni ham ketgazganida bugun tun bo’yi shalobbo bo’lgan bo’lardim…", "date": "2023-02-04", "lang": "uz", "tags": ["rainy_mood"], "body": "Aslida gunohlarni kafforati - tavbadir. Va uning eshigi hamisha ochiq&#33; <br><br>Ya Alloh, tavbalarimizni O’zing qabul ayla va bizlarni mag’firat et&#33;&#33;&#33;", "excerpt": "Aslida gunohlarni kafforati - tavbadir. Va uning eshigi hamisha ochiq! Ya Alloh, tavbalarimizni O’zing qabul ayla va bizlarni mag’firat et!!!", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/615"}, {"id": 598, "slug": "first-598", "title": "Xufton tahorati bilan Bomdod o’qishgan o’sha buyuk zohidlarning …", "fullTitle": "Xufton tahorati bilan Bomdod o’qishgan o’sha buyuk zohidlarning -", "date": "2023-01-31", "lang": "uz", "tags": ["cant_sleep", "night_thoughts"], "body": "Xuftondan keyinoq telfonni olib, kechasi bilan uxlamay, Bomdodga uyg’onolmayotgan avlodlari bo’ldik…<br><br>P.s: <i>uxlaylik endi, bu nafs &quot;telfon o’ynab” hech to’ymaydi baribir</i>", "excerpt": "Xuftondan keyinoq telfonni olib, kechasi bilan uxlamay, Bomdodga uyg’onolmayotgan avlodlari bo’ldik… P.s: uxlaylik endi, bu nafs \"telfon o’ynab” hech…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/598"}, {"id": 583, "slug": "first-583", "title": "Ko’zgu bo’lish", "fullTitle": "Ko’zgu bo’lish", "date": "2023-01-25", "lang": "uz", "tags": [], "body": "[Yoxud konstruktiv tanqid]<br><br>Ayrim insonlar ba’zida ularga qilayotgan ishlari noto’g’riligi aytilgan paytda jahllari chiqadi…<br><br>Aslida aksincha bo’lishi kerak<br><br>Musulmon inson boshqa bir musulmonga ko’zgu kabi bo’lmog’i lozim&#33;<br><br>Eng yaxshi, yaqin do’stlar ham shunaqa: kamchiliklaringni shartta yuzingga aytishadi<br><br>Eng yaxshi do&#39;st(dugona), turmush o’rtoq, ustoz, o’quvchi…kamchiligingni ko’rsa darrov o’zingga aytadigani<br><br>Hammani oldida emas - o’zingga aytadigani<br><br>Oldinlari kimdur mani xatolarimi etsa, o’sha insonni yomon ko’rib qolardim - ammo hozir eng yaxshi ko’radiganlarim xato qilsam o’zimga kelib: qachon, qayerda, qanday xato qilganimni aytadiganlar", "excerpt": "[Yoxud konstruktiv tanqid] Ayrim insonlar ba’zida ularga qilayotgan ishlari noto’g’riligi aytilgan paytda jahllari chiqadi… Aslida aksincha bo’lishi…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/583"}, {"id": 567, "slug": "first-567", "title": "O’zbekcha tarbiya modeli", "fullTitle": "O’zbekcha tarbiya modeli", "date": "2023-01-19", "lang": "uz", "tags": [], "body": "Hich sezganmisila, bizda ko’pchilik Yevropa ma’daniyatini yomonledi:<br><br>Ularda farzandini 18yoshdan keyin ko’chaga chiqarvorishadi…”mustaqil hayot”ga o’rgatisharmish…<br><br>Mana biz o’zbeklarda mehr-oqibat bor,-diyishadida<br>“Bolasini - bolasigacha katta qiladi”<br><br>Shunchunam ko’chada yurganizda 30-40 yoshli yosh bollarni ko’rib qolasiz ba’zida<br><br>©️Mirshakar Fayzulloyev<br><br>Rostan, mangayam ko’pincha haddan tashqari oshirib yuborishadigandek ko’rinadi<br><br>San uchun hamma qarorni o’zlari qabul qilishadi… <br><br>- <code>nima yeb, nima ichishing, qaysi fandan “repititor”ga borishing, qaysi o’quv markazga borishing, qaysi universitetga kirishing-u, u yerni bitirib qayerda kim bo’lib ishlashing, kim bilan oila qurishinggacha hammasi nazorat ostida&#33; </code><br><br>Eng qizig’i: o’zing hech narsa tanlab - sotib ololmaysan; qo’pol bo’lsa ham, hatto ichki kiyimlaringgacha o’zlari olib berishadi<br><br>To’g’ri tushunaman, ota-ona farzindiga yomonlikni ravo ko’rmedi, hardoim yaxshi bo’lishimizni xohlashadi<br><br>Lekin: hech kim ularni farzandlari bilan bir-umr yashashlariga kafolat bermagan…<br><br>Bu juda kotta risk ya’ni ertadan keyin ular olamdan o’tgach, ota-onasiga butunlay tayanib qolgan farzand qay ahvolga tushadi, hayotini uyog’iga qanday davom ettiradi?<br><br>Aslida, ota-onaning farzandi uchun qilgan eng katta yaxshiligi bu dunyoda ularsiz ham hayrli amallar qilib yashashga, ularsiz ham to’g’ri qarorlar qabul qilishga o’rgatish&#33;<br><br>Ammo bu ishga bizning o’zbekcha tarbiya modelimiz yo’l qo’ymaydi…<br><br>P.s: <i>aytmoqchi bo’layotganim: ozgina erkinlik va bolaga o’zi uchun o’zi qaror qabul qilishiga imkon berish kerak.<br>To’g’ri qilsa, o’ziga ishonchi ortadi&#33;<br>Agar xato qilsa, o’rganadi&#33;<br>Balki menga o’xshab sekin asta ota-onani qadriga yetishni, ularni ham tushinishni, ular uchun ham qayg’urishni boshlar :)</i>", "excerpt": "Hich sezganmisila, bizda ko’pchilik Yevropa ma’daniyatini yomonledi: Ularda farzandini 18yoshdan keyin ko’chaga chiqarvorishadi…”mustaqil hayot”ga…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/567"}, {"id": 563, "slug": "first-563", "title": "Rozimisiz?", "fullTitle": "Rozimisiz?", "date": "2023-01-17", "lang": "uz", "tags": [], "body": "O&#39;zini tanigan, Dinini oz-moz tushungan mo&#39;min-musulmonda yoki muslimada oliy maqsad bitta bo&#39;ladi, bir xil bo&#39;ladi:<br><br><b>Alloh roziligini topish</b><br><br>Barchamiz shu maqsadda yashemiz, ishlemiz, o&#39;qiymiz...<br><br>Mana siz ham Alloh Subhanahu va Taolo sizdan rozi bo&#39;lishligini xohlayapsiz<br><br>Endi savol: <b>Siz ham Allohdan rozimisiz???</b><br><br>- Iya, qande qilib Allohdan rozi bo&#39;lishim mumkin, axir manku Uning rizoligini istab yurgan...<br><br>Javob: Robbingizni sizga bergan ne&#39;matlari, yaxshiliklari uchun hursand bo&#39;lganingiz kabi ~ boshingizga musibat, g&#39;am-tashvish tushgan paytda sabr qilib, bardosh qilishingiz Allohdan roziligingiz alomati bo&#39;ladi.<br><br>Agar hayotingizda sizga yoqmaydigan ishlar sodir bo&#39;lsa, musibat keganda sabr qilolmayotgan bo&#39;sez, demak siz Allohdan rozi emassiz<br><br><b>Undan o&#39;zingiz rozi bo&#39;lmay turib, qanday qilib Uning rizoligiga erishmoqchisiz?&#33;</b><br><br>P.s: <i>Abdulloh domladan Alloh rozi bo&#39;sin, ko&#39;plab darsliklari bor... Ilm o&#39;rganish uchun eng go&#39;zal va qulay manba</i>", "excerpt": "O'zini tanigan, Dinini oz-moz tushungan mo'min-musulmonda yoki muslimada oliy maqsad bitta bo'ladi, bir xil bo'ladi: Alloh roziligini topish…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/563"}, {"id": 552, "slug": "first-552", "title": "Odatlar shakllantirish", "fullTitle": "Odatlar shakllantirish", "date": "2023-01-15", "lang": "uz", "tags": [], "body": "Inson avval odatlar shakllantiradi, keyin ana o&#39;sha odatlar insonni shakllantiradi&#33;<br><br>Odat o&#39;zi nima?<br>- Odat bu inson har kuni biror vaziyatda avtomatik tarzda bajaradigan ishi<br><br>Ya&#39;ni odat har kuni, har safar qaytarilaverganidan uni bajarishdan oldin o&#39;ylab o&#39;tirilmaydi<br><br>Masalan qo&#39;ng&#39;iroq bo&#39;ldi sizga, telefon go&#39;shagini ko&#39;tardiz va:<br>- Al&#39;o (Alyo&#39;) <br>Kimlardadur shu:<br>- Assalamu alaykum, eshitaman<br><br>Yoki ertalab uyg&#39;ondizda telfonizi oldiz...<br>Kimlardur ertalab uyg&#39;onishi bilan o&#39;rnidan turib joyini &quot;zapravka&quot; qiladi<br><br>Odatlar 2xil bo&#39;ladi:<br>- Yaxshi &amp; foydali<br>- Yomon &amp; foydasiz<br><br>Sizi kundalik hayotizda qaysi biri ko&#39;proqligini bilish uchun tahlil qilib chiqishiz kere...<br><br>Bir varoq oppoq listni olamiz, yoki daftar <br>Bir kunimizi bir boshidan yozib chiqamiz:<br><br>Ertalab turiboq nima qilaman<br>Nonushtadan oldin nima qilaman<br>Kiyin nima qilaman<br>Telfonimga sms kelsa nima qilaman<br>Qo&#39;ng&#39;iroqqa javob berganda nima diyman<br>Telfon o&#39;ynashdan oldin nima qilaman<br>Instagramga kirib nima qilaman<br>YouTubega kirib shorts ko&#39;ramanmi yo video qidirib o&#39;zim topib ko&#39;ramanmi<br>Kitob o&#39;qishdan oldin nima qilaman<br>... <br><br>Keturadi ertalabdan to kechgacham nima ishla qilishizi yozib chiqasiz va keyin tahliliga o&#39;tasiz<br><br>Tahlil paytida mana bu manga foydali, mana buni ne unaqa qilaman o&#39;zimam bilmiman, buni bir tiynli foydasi yo&#39; manga... dib ajratib yozib chiqasiz<br><br>Va oxirgi qadam, sizga nafi tegmayotgan vaqtizni bekorga ketib qolishiga sabab bo&#39;layotgan odatlarizi o&#39;rniga boshqa yangi manfaatliroq, yaxshi odatlarni shakllantirishni boshlasez bo&#39;ladi&#33;&#33;&#33;", "excerpt": "Inson avval odatlar shakllantiradi, keyin ana o'sha odatlar insonni shakllantiradi! Odat o'zi nima? - Odat bu inson har kuni biror vaziyatda…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/552"}, {"id": 538, "slug": "first-538", "title": "Inson tanigan kimsasini yaxshi ko'radi", "fullTitle": "Inson tanigan kimsasini yaxshi ko'radi", "date": "2023-01-13", "lang": "uz", "tags": [], "body": "Biz hammamiz ota-onamizni yaxshi ko&#39;ramiz&#33;<br><br>Endi tasavvur qiling, bir kuni sizga notanish ikki inson kelib: &quot;Biz seni haqiqiy ota-onangmiz...&quot; deyishdi<br>Uyga kelib dadezdan, oyizdan so&#39;radiz bu rostmi yolg&#39;onmi<br>Ular tasdiqlashdi: &quot;Ha ana o&#39;shalar seni haqiqiy ota-onang, chaqaloqligingda seni bizga berib ketishgandi...&quot;<br><br>Savol: shu payt siz o&#39;ziz hurmat qilgan, shu paytgacha birga yashagan, siz tanigan bu ikki insonni birdan yomon ko&#39;rib qolasmi?<br><br>Yoki siz shu kungacha biror marta ko&#39;rmagan, eshitmagan, tanimagan boshqa ikki insonni birdan yaxshi ko&#39;rib qolasmi???<br><br>Yòq<br><br>Chunki inson tanigan kimsasini yaxshi ko&#39;radi. Tanimasa, bilmasa qanday yaxshi ko&#39;radi?<br><br>Tanish esa yaqin bo&#39;lishlik, uzooq suhbatlashishlik, qalban yaqin bo&#39;lishlik va bog&#39;lanishlik bilan bo&#39;ladi<br><br>Xuddi shu singari inson <a href=\"https://youtu.be/QBWNQMlqwf4\" target=\"_blank\" rel=\"noopener\">Allohni sevishi</a> va Uning Rasuli(s.a.v) ga muhabbatli bo&#39;lishi uchun, avval Ularni tanishi kerak&#33;<br><br>Tanish uchun nimalar qilish kerakligini gaplashdik...<br><br>Allohga muhabbati bor odam, Uning ibodatida bardavom bo&#39;ladi, U buyurgan amallarni bajaradi va Uning qaytariqlariga sòzsiz itoat qiladi<br><br>Rosululloh s.a.v ni yaxshi ko&#39;rgan odam Sunnatga amal qiladi, Ulardan o&#39;rnak oladi, Hadislariga quloq tutadi.<br>Sababi Ular ham uni sevishlarini his qiladi.<br><br>Alloh bandalarini yaxshi ko&#39;radi... <br>Agar olamlarni yaratgan Zot bizni sevmasa, yaratgan bo&#39;larmidi?<br>Bizga muhabbat qilmasa, O&#39;zini tanitgan bo&#39;larmidi???<br><br>Haqiqiy muhabbat isboti bilan bo&#39;ladi<br><br>&#39;Men Alloh va Rosulini yaxshi ko&#39;raman&#39; diyishlik, agar bandani amallarida sezilmasa, demak u yolg&#39;on gapiryapti&#33;<br><br>P.s: <i>Ya Robbiy, sevaman demoqlikka jur&#39;atim yetmas... :(</i>", "excerpt": "Biz hammamiz ota-onamizni yaxshi ko'ramiz! Endi tasavvur qiling, bir kuni sizga notanish ikki inson kelib: \"Biz seni haqiqiy ota-onangmiz...\"…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/538"}, {"id": 535, "slug": "first-535", "title": "O'limni eslash", "fullTitle": "O'limni eslash", "date": "2023-01-12", "lang": "uz", "tags": [], "body": "Har safar o&#39;limni eslaganda, ichimizda qandaydur qo&#39;rquv aralash o&#39;zgacha hissiyot paydo bo&#39;ladi...<br><br>Savol tug&#39;iladi, manda tug&#39;ilgan, siladayam tug&#39;ilgan bo&#39;lishi mumkin:<br><br>- Inson hardoim o&#39;limni eslab yursa, tushkunlikka tushib qomidimi? <br>- Hursandchilikla yòqolib qomidimi?<br>- Mazza qime qòymidimi hayotdan?<br>- Yashashdan ma&#39;no yo&#39;qolib qomidimi?<br><br>Man topgan javoblar:<br><br>- Yo&#39;q, aksincha tushkinlikdan chiqishi, o&#39;zi umuman tushkunlikka tushmaslikka sabab bo&#39;lishi mumkin&#33;<br>- Hursandchilik, hayotda mazza qilib yashashga kelsak, nimadan hursand bo&#39;lishiz, nimalardan mazza qilishiz o&#39;zgarishi mumkin...<br>Endi hursandchilik boshqa narsalardan kelishni boshlidi, boshqalarga yaxshilik qilib hursand bo&#39;lasiz.<br>Endi boshqa ishlardan kayf qilishni boshlisiz, ibodatdan, hayr-ehsondan, ilm o&#39;rganishdan mazza qilish boshlanadi&#33;<br><br>- Yashashdan ma&#39;no yo&#39;qolib qomidi... Aksincha topiladi&#33; Nimaga yashavotganizi anglisiz, maqsadlarizi &quot;сортировка&quot; qilishshi boshlisiz&#33;<br><br>Umuman olganda ~ o&#39;limni eslash bilan ko&#39;p narsalarga erishamiz&#33;<br><br><i>Har doim, har soniyada eslab turolmasak ham, hich bo&#39;maganda unitmasligim kerak, manimcha :)</i>", "excerpt": "Har safar o'limni eslaganda, ichimizda qandaydur qo'rquv aralash o'zgacha hissiyot paydo bo'ladi... Savol tug'iladi, manda tug'ilgan, siladayam…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/535"}, {"id": 536, "slug": "first-536", "title": "Mahzun bo'lma", "fullTitle": "Mahzun bo'lma", "date": "2023-01-12", "lang": "uz", "tags": [], "body": "Iching to&#39;la darding bor...<br>Lekin hich kimga ayta olmaysan<br><br>Qalbing to&#39;la orzu-umidlar...<br>Lekin hech biriga yeta olmaysan<br><br>Hayoting to&#39;la qiyinchiliklar...<br>Lekin qo&#39;l siltab keta olmaysan<br><br>Boshingda ming xil hayollar...<br>Lekin o&#39;ylab-o&#39;ylab, oxiriga hich yeta olmaysan<br><br>&quot;Men&quot;ingda savollar bisyor...<br>Lekin javob topa olmaysan<br><br><i>Mahzun bo&#39;lma ~ Alloh hamisha sen bilan&#33;&#33;&#33;</i><br><br><b>&quot;La tahzan innallaha ma&#39;ana&quot;<br>  ؓ لَا تَحْزَنْ إِنَّ اللَّـهَ مَعَنَا<br>(</b><a href=\"http://www.youtube.com/watch?v=GvTDtpx6NKI\" target=\"_blank\" rel=\"noopener\"><b>9:40</b></a><b>)</b>", "excerpt": "Iching to'la darding bor... Lekin hich kimga ayta olmaysan Qalbing to'la orzu-umidlar... Lekin hech biriga yeta olmaysan Hayoting to'la…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/536"}, {"id": 533, "slug": "first-533", "title": "Hammamiz ham o'lamiz", "fullTitle": "Hammamiz ham o'lamiz", "date": "2023-01-11", "lang": "uz", "tags": [], "body": "Kimdur erta, kimdur kech - baribir bir kun bu dunyoni tark etamiz&#33;<br><br>Ba&#39;zida shu oddiy haqiqat yodimizdan ko&#39;tarilib qoladi...<br><br>&quot;Eslating, zero eslatma mo&#39;minlarga manfaat yetkazur&quot;<br><br>Qachonki:<br>• Puliz ko&#39;p bo&#39;lib boyib ketsez<br>• Mashxur bo&#39;lib, obunachilariz milliondan oshsa<br>• Universitetga kirsez (grantga)<br>• Biznes qilib, kotta biznesmen bo&#39;pketsez<br>• Mukofotlar osez (Faxriy yorliq, Nobel...)<br><br>Esizdan chiqmasin birodar, baribir bir kuni o&#39;lasiz&#33;&#33;&#33;<br><br>Qachonki:<br>• Ishlariz yurishme qosa<br>• Kambag&#39;allikdan qiynalyotgan bo&#39;sez<br>• Sizni hich kim tanimasa (obunachilariz kam bo&#39;sa)<br>• Universitetga kirolmasez (kontraktga bo&#39;sayam)<br>• Oddiy ishchi bo&#39;sez, oyligiz zòrg&#39;a yetib turgan bo&#39;sa<br>• Hich qanaqa mukofot omagan bo&#39;sez<br><br>Unutmang, baribir bir kun o&#39;lasiz&#33;&#33;&#33;<br><br>Aytmoqchi bo&#39;lganim bularni hech biri sizni hursand yoki hafa qilishi keremas... Chunki o&#39;lim kelganda hech biri siz bilan birga ketmedi, yolg&#39;iz o&#39;ziz va amallariz qoladi&#33;<br><br><b>&quot;You could leave life right now...&quot;</b><br><br>Nimadur qilishdan, nimadur diyishdan oldin o&#39;ylab ko&#39;ring: &quot;Shu ishni qilyotib o&#39;lib qosamchi? Shu gaplar mani oxirgi gaplarim bo&#39;sachi?&quot;<br><br>Oyiz bilan gaplashvossiz: shu so&#39;nggi suhbatiz bo&#39;pqolishi mumkin<br>Ukez bilan urishvossiz: shu uni oxirggi marta ko&#39;rvotgan paytiz bo&#39;lishi mumkin<br>Kimnidur rosa so&#39;kvossiz: shu og&#39;zizdan chiqqan so&#39;nggi so&#39;zlar bo&#39;pqolishi mumkin<br>Telfon o&#39;ynab o&#39;tiribsiz: shu umrizi so&#39;nggi daqiqalari bo&#39;lishi mumkin<br><br>Hich kimga paloncha yil umr kafolat berilmagan, olayotgan nafasiz so&#39;nggisi bo&#39;lishi mumkin...<br><br>P.s: <i>Abadiy umr ko&#39;radigandek yashashni to&#39;xtataylik...</i><br><br><b>O&#39;lim haqida eslash, bizga nima muhim - nima muhimmasligini aniqlashtirishga yordam beradi&#33;</b><br><br>Mana shu postni yozvomman, vaqtim umrim ketvotti<br> ~ muhim dib o&#39;ylaganim uchun yozvomman, bo&#39;masa yozmasdim<br><br>Siz ham endi buyog&#39;iga o&#39;ziz uchun hal qilvoling: chunki o&#39;lim kelajakdamas, u har soniya eshik qoqmoqda...<br>Albatta ajal kelganda, uning oldida ojizmiz&#33;", "excerpt": "Kimdur erta, kimdur kech - baribir bir kun bu dunyoni tark etamiz! Ba'zida shu oddiy haqiqat yodimizdan ko'tarilib qoladi... \"Eslating, zero eslatma…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/533"}, {"id": 507, "slug": "first-507", "title": "O'ylab qarasam vaqtimni ko'p qismini nimadur qilish o'rniga, o'sha…", "fullTitle": "O'ylab qarasam vaqtimni ko'p qismini nimadur qilish o'rniga, o'sha ishni qilishim haqida gapirib o'tkazyotgan ekanman... :(", "date": "2022-12-13", "lang": "uz", "tags": ["realization"], "body": "🗣 Odatlar shakllantiraman, kitoblar o&#39;qiyman, podcastlar chiqaraman 🗣<br><br>Soat tungi 12 bo&#39;lyapti, serial ko&#39;rib yotibman... Qanday maraz odamligimni sezyapsizmi?<br><br>P.s: <i>Balki nafsga qarshi kurash ochish vaqti kelgandur</i>", "excerpt": "🗣 Odatlar shakllantiraman, kitoblar o'qiyman, podcastlar chiqaraman 🗣 Soat tungi 12 bo'lyapti, serial ko'rib yotibman... Qanday maraz odamligimni…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/507"}, {"id": 506, "slug": "first-506", "title": "Ego is the enemy", "fullTitle": "Ego is the enemy", "date": "2022-12-12", "lang": "uz", "tags": [], "body": "Ego - haqiqiy dushman...<br><br>Bu so&#39;z o&#39;zbekchada - nafs deyilsa kerak. <br>Biz bilan hardoim, har daqiqa va har soniyada yonimizda bo&#39;ladigan yagona dushmanimiz&#33;<br><br>Ryan Holidayning shu kitobini o&#39;qir ekanman - bir narsa e&#39;tiborimni ko&#39;proq tortdi: Gapirish va qilish o&#39;rtasidagi munosabat<br><br>Ya&#39;ni biri ikkinchisini o&#39;ldiradi, ma&#39;nosi agar siz qiladigan, rejalashtirgan ishlariz haqida og&#39;izni ko&#39;pirtirib gapirar ekansiz, haqiqat shuki: o&#39;sha ishlarni qilish ehtimoli pasayar ekan.<br><br>Man shu paytgacha teskarisini o&#39;ylardim...<br>Gapirib qo&#39;yarkan, unda endi ma&#39;suliyat ham bor, qilish ehtimolligi ortadi. Yo&#39;q&#33; Ko&#39;pincha unday emas:<br><br>Men bu ishni qilyapman, u ishni qilmoqchiman deb dunyoga jar solar ekanmiz, nafsimiz huzur topishni boshlaydi, ya&#39;ni bu narsa &quot;ego&quot;imizga yoqadi. Haqiqiy ishni qilishga kelganda esa &quot;u&quot;ni endi ko&#39;ndirib bo&#39;psiz<br><br>Shu payt bir maqolmiye (gapmi, bilmadim nima) esimga tushdi: &quot;Gap desa qop, qop - ish desa Samarqanddan top&quot; deyishardi kattalar...<br><br>Qisqasi oldimizda ikkita tanlov bor: <br>To be or To do? <br>(Kimdur bo&#39;lish yoki nimadur qilish)<br><br>Bir tomonda: a) Ijtimoiy tarmoqlarda o&#39;zini ko&#39;rsatib, hammani e&#39;tiborini tortishga urinayotgan, o&#39;zlarini &#39;influencer&#39; qilib ko&#39;rsatayotganlar bor. Egolari kuchliligidan faqat gapiradilar xolos...<br><br>Boshqa tomonda: b) Rostan ham nimadur foydali ishlar qilib, jamiyatga haqiqiy qiymat berayotgan odamlar bor, ularni ko&#39;pchiligi haqida eshitmaganmiz, ko&#39;rmaganmiz. Sababi ular band = Instagramda 2soatlab &quot;primoy efir&quot; qilib, qilayotgan ishlari haqida gapirib o&#39;tirishga vaqtlari yo&#39;q...<br><br>Siz qaysi tomondasiz yoki bo&#39;lmoqchisiz?<br>Agar a) taraf bo&#39;ladigan bo&#39;lsa, okay: odamlarga ular eshitishni xohlagan narsalarini aytishni boshlang. Topayotgan pullariz, orttirgan obroyiz, kirgan universitetlariz, yutgan scholarshiplarizi maqtaning&#33; Axir hammasiga o&#39;ziz erishdizku...<br><br>Yoki nafsga qarshi ozgina kurashingda, sizni &quot;olqishlash&quot;larini kutmasdan, qilishingiz kerak bo&#39;lgan, o&#39;zizga, oilangizga va butun ummatga foyda bo&#39;ladigan ishlarni qilishni boshlang&#33;&#33;&#33;<br><br>Vaqti keladi: o&#39;zlari sizni tan olishadi. Muhimi maqsad va niyatni to&#39;g&#39;rilab olish&#33;<br><br>P.s: <i>Proyektlarimizni to&#39;xtatib turamizmi diymanda)</i>", "excerpt": "Ego - haqiqiy dushman... Bu so'z o'zbekchada - nafs deyilsa kerak. Biz bilan hardoim, har daqiqa va har soniyada yonimizda bo'ladigan yagona…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/506"}, {"id": 505, "slug": "first-505", "title": "Orzular ushalmasligi ham mumkin", "fullTitle": "Orzular ushalmasligi ham mumkin", "date": "2022-12-10", "lang": "uz", "tags": [], "body": "Qanchalik harakat qilmang, qanchalar qattiq kurashmang, agar peshonangizda bo&#39;lmasa, baribir foydasi yo&#39;q&#33;<br><br><b>Lekin</b> bu digani harakat qilmaslik kerakligini anglatmaydi... <b>Harakatdan to&#39;xtamas ekansiz</b>, <i>deylik orzuyingiz ushlamagan taqdirda ham</i>, <b>siz shubhasiz dunyodagi eng topdagi shaxsga aylanasiz&#33;&#33;&#33;</b><br><br>Bularni qayerdan bilasan desangiz, men shunchaki Ronaldoni hayotiga nazar tashladim xolos&#33; Hozir futboldan biroz yiroqlab qolgan bo&#39;lsamda, ich-ichimdan unga qo&#39;shilib yig&#39;lagim keldi...<br><br><b>Lekin anniq bilaman, Ronaldo - sen &#39;World Cup&#39;siz ham eng zo&#39;risan, bro&#33;</b>", "excerpt": "Qanchalik harakat qilmang, qanchalar qattiq kurashmang, agar peshonangizda bo'lmasa, baribir foydasi yo'q! Lekin bu digani harakat qilmaslik…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/505"}, {"id": 483, "slug": "first-483", "title": "Odamlar nima deydi?", "fullTitle": "Odamlar nima deydi?", "date": "2022-11-14", "lang": "uz", "tags": [], "body": "Judayam og&#39;riqli &quot;tema&quot;larimizdan biri...<br><br>Va man yaqinda xuddi shu mavzuda batafsil muhokama qilingan ko&#39;rsatuv ko&#39;rdim. Bu ko&#39;rsatuvda bu streotip oqibatida qanday ishlar kelib chiqayotgani, iqtisodiyot ta&#39;siri, psixologik va diniy taraflama yechim va tavsiyalar berilgan&#33;<br><br>Ko&#39;rsatuvni ko&#39;rish -&gt; <a href=\"https://youtu.be/6dwrdcrdUSA\" target=\"_blank\" rel=\"noopener\">YouTube</a><br><br><i>Ba&#39;zan qaysidur mavzularda postlar yozgim kelardi-da, lekin yozolmasidim... nu o&#39;ylab qarasam aslida &quot;Odamlar nima deydi? digan narsa to&#39;sayotganidikan maniyam.</i><br><br><b>Balki bu kabi fikrlashni kamaytirishimiz vaqti kelgandur... Nima disila?</b><br><br>Aaa uzur kommentariyada hammayam o&#39;z fikrini boricha yozolmedi, chunki yozsa odamlar nima deydi???", "excerpt": "Judayam og'riqli \"tema\"larimizdan biri... Va man yaqinda xuddi shu mavzuda batafsil muhokama qilingan ko'rsatuv ko'rdim. Bu ko'rsatuvda bu streotip…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/483"}, {"id": 459, "slug": "first-459", "title": "Birinchi stand-up 🎤", "fullTitle": "Birinchi stand-up 🎤", "date": "2022-09-10", "lang": "uz", "tags": [], "body": "Kuchli hayajon, ozroq qo&#39;rquv va ikkilanish bilan boshlandi...<br><br>Lekin judda kotta experience bo&#39;ldi man uchun, unaqa sahnada, o&#39;shancha tomoshabinni oldida bir o&#39;zim, mikrafonam yo&#39;q qo&#39;limda😁<br><br>4 minutlik chiqish... birinchi bo&#39;lib sahnaga chiqdim... o&#39;rtada hazilim esimdan chiqib qoldi... xullas 1-martasiga qanday bo&#39;lishi kerak bo&#39;gan bo&#39;sa o&#39;shanday chiqish bo&#39;ldi, nazarimda<br>Yana bilmadim, bu so&#39;zlarni o&#39;zimmi ovutish uchun o&#39;ylab topayotgan bo&#39;lishimam mumkin🤷‍♂️<br><br>Kelib, от души qo&#39;llab-quvvatlaganlarga, o&#39;zi kelolmasayam, omad tilab manga kuch bag&#39;ishlaganlarga RAHMAT😇<br>Borilarga shukur☺🙃<br><br><i>O&#39;ylaymanki hazillar yoqdi, mazza qildizla digan umiddaman, eng muhimi sarflagan vaqtilaga achinmagan bo&#39;sela bo&#39;ldi :)</i><br><br>Kelolmaganlarga: ertaga kichkina videocha tashlab beraman, o&#39;shanda ko&#39;rvolasila endi😉", "excerpt": "Kuchli hayajon, ozroq qo'rquv va ikkilanish bilan boshlandi... Lekin judda kotta experience bo'ldi man uchun, unaqa sahnada, o'shancha tomoshabinni…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/459"}, {"id": 457, "slug": "first-457", "title": "Nimaga?", "fullTitle": "Nimaga?", "date": "2022-09-08", "lang": "uz", "tags": [], "body": "[Ta&#39;lim tizimi -&gt; Made in Uzbekistan]<br><br>9-sinfdan beri mamlakatimizdagi ta&#39;lim tizimi haqida savollarga javob oxtaraman...<br><br><i> - Nimaga maktablarimizda, universitetlarda forma, galstuk shunchalik qattiq talab qilinadi, bilim emas?</i><br><br><i>- Nimaga o&#39;qituvchilarimiz bizning miyamizni yaxshi, to&#39;liq va eng asosiysi kerakli bilimlar bilan to&#39;ldirish o&#39;rniga, jurnal...xujjatlar to&#39;ldirishadi?<br><br>- Nimaga maktab remontiga o&#39;quvchilar, ota-onalardan pul olinadi? Axir bu davlat maktabi-ku??? <br><br>- Nimaga metallom, makilatura, obuna, yosh kuch... degan narsalarga pul beramiz? Umuman nimaga mavjud unaqa narsalar?<br><br>- Nimaga darsda faqat o&#39;qituvchi gapiradi? O&#39;quvchilar faqat eshitadi? O&#39;z fikrlarini bemalol aytolmedi? <br></i><br><b>Nimaga, nimaga, nimagaaa???</b><br><br>Ayrimlariga javob topganman o&#39;zimcha.<br>Javobsizlari ko&#39;p hali...<br><br>Subtektivdan navbatdagi bomba video - <br><a href=\"http://www.youtube.com/watch?v=eGp6VIVzyIk\" target=\"_blank\" rel=\"noopener\">O&#39;zbekistonda ta&#39;lim illuziyasi - Oliy Ta&#39;lim</a><br><br>Bu sonda asosan Oliy Ta&#39;limdagi &quot;ahvolimiz&quot; haqida gap borgan.<br><br>Maktabgacha, Boshlang&#39;ich va O&#39;rta ta&#39;limda ham yetarlicha muammolarimiz bor va keyingi sonlarda shular haqida tanqidiy ko&#39;rsatuv bo&#39;lishini kutib qolardim.<br><br>Bu negativchilikmas, bu voqeaga real qarash va shunchaki jamiyatga ko&#39;zgu tutish... achchiq lekin haqiqatlar<br><br><b>To&#39;g&#39;ri, o&#39;zgartirish uchun ko&#39;p ishlar qilinishi kerak, lekin manimcha birinchi qadam muammolarni tan olishdan boshlanadi&#33;</b><br><br><i>Fikrlar subtektiv - xulosa har kimni o&#39;zidan</i>", "excerpt": "[Ta'lim tizimi -> Made in Uzbekistan] 9-sinfdan beri mamlakatimizdagi ta'lim tizimi haqida savollarga javob oxtaraman... - Nimaga maktablarimizda…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/457"}, {"id": 454, "slug": "first-454", "title": "Siz o'xshashni hoxlaydigan inson(lar)", "fullTitle": "Siz o'xshashni hoxlaydigan inson(lar)", "date": "2022-09-06", "lang": "uz", "tags": [], "body": "Hayotda kimdur kimdurga o&#39;xshagisi keladi: boylik jihatidan, mashxurlik tomonlama, obro&#39;-e&#39;tibor nuqtai nazaridan, yashash tarzi va hokazo.<br><br>Aziz aka Rakhimov bu borada shunday bir fikr aytgan: &quot;Fanatlik 2turda bo&#39;lishi mumkin&quot;<br><br>- Birinchisi, fanat bo&#39;gan insonini kiygan kiyimlarini kiyadi, eshitayotgan qo&#39;shiqlarini eshitadi, ko&#39;rinishini usha insonga o&#39;xshatishga harakat qiladi va bu eng oson yo&#39;l ko&#39;pchilik shu yo&#39;lni tanledi lekin  natijada unda hich narsa o&#39;zgarmedi, o&#39;smedi, rivojlanmediyam<br><br>- Ikkinchi turdegisi, o&#39;sha o&#39;zi kumir dib bilgan insonini fikrlashini o&#39;rganadi, o&#39;qiyotgan kitoblarini o&#39;qiydi, u qiladigan ishlarga o&#39;xshedigan ishlani qiladi, u boradigan joylarga boradi va natijada o&#39;ziyam o&#39;zgaradi, o&#39;sadi.<br><br><b>Siz kimning fanatisiz???</b><br><br>Biz musulmonlar, hammamiz suyukli Payg&#39;ambarimiz Muhammad Mustafo (s.a.v) ning fanatlarimiz. Ularni qilgan ishlarini qilib, sunnatlariga amal qilib borsak, natijada o&#39;zimizam o&#39;sib rivojlanib boruramiz&#33;", "excerpt": "Hayotda kimdur kimdurga o'xshagisi keladi: boylik jihatidan, mashxurlik tomonlama, obro'-e'tibor nuqtai nazaridan, yashash tarzi va hokazo. Aziz aka…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/454"}, {"id": 455, "slug": "first-455", "title": "Metroda yurish foydali(mi?)", "fullTitle": "Metroda yurish foydali(mi?)", "date": "2022-09-06", "lang": "uz", "tags": [], "body": "Yoxud zerikishning siz bilmagan foydalari<br><br>Toshkentga kelgan odamlar(ko&#39;pchilik talabalar, balki hammalari) uchun Metro asosiy transport vositasiga aylanadi<br><br>Man ham kelganimdan beri faqat metroda yuripman(yurvomman disamam bovuradi :)<br><br>Ko&#39;pincha kuzatgan holatlarim:<br>• Metroda ko&#39;pchilikni qulog&#39;ida naushnik bo&#39;larkan - baland shoqinni eshitishni hoxlashmas balki<br>• Turli xil odamlar, turli xil viloyatlardan, turli xil nigohlar...<br>• &quot;Yevropeskiy&quot; qizlardan ko&#39;z uzolmay qarab turgan &quot;yigitlar&quot;...<br>• 80% odam(taxminan) balki undanam ko&#39;prog&#39;i telfonga termulgancha ketadi...<br>(Man ham hozir shularni shunday xolatda metroda yozyapman)<br>• E&#39;tiborsizlik avjida, birovni birov bilan ishi yo&#39;q... <br>• Hamma qayergadur shoshgan...<br><br>Oxirgi paytlarda kuzatishni boshladim: odamlarni, atrof-muhitni. Avvaliga zerikishni boshladim, qo&#39;limga telfonni olgim kelaverdi... lekin hozir ancha o&#39;rganib qoldim.<br><br>Aytmoqchi bo&#39;lyotganim har safar qayerda bo&#39;lsangiz ham, metrodami, ko&#39;chadami, zerikishni boshlaganizda shartta telfonni olib, bir nimalar qilib chalg&#39;ishga harakat qilavermang&#33;<br><br><b>Zerikibam turish kerak ekan odamzot&#33;</b> <br>Nimadur qilaverib emas, hich narsa qilmasdan zerikish...<br><br>Shunda - fikrlar teran bo&#39;lishi, creativlik va kuchli tasavvur qilish, analitika ham qaysidur ma&#39;noda sekin sekin rivojlanishiga guvoh bo&#39;lasiz.<br><br>Buguncha kech bo&#39;ldi, ertaga nasib qilsa albatta, bir shunday qilib ko&#39;ring, atrofdagi insonlarni, voqealarni kuzating...<br><br><i>Va keyinchakik o&#39;z fikrlarizi kommentda ulashishni ham unutmang :)</i>", "excerpt": "Yoxud zerikishning siz bilmagan foydalari Toshkentga kelgan odamlar(ko'pchilik talabalar, balki hammalari) uchun Metro asosiy transport vositasiga…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/455"}, {"id": 453, "slug": "first-453", "title": "Comfort 🔜 Discomfort", "fullTitle": "Comfort 🔜 Discomfort", "date": "2022-09-04", "lang": "en", "tags": [], "body": "I&#39;m about to start the most challenging part of my life by moving to Tashkent <br><br>Staying in the comfort zone isn&#39;t the way of successful people...<br><br>The earlier you leave the comfort zone, the more chances you can get to have a better future&#33;<br><i><br>Are you in your comfort zone now?<br>What was the last time you did something discomforting???</i>", "excerpt": "I'm about to start the most challenging part of my life by moving to Tashkent Staying in the comfort zone isn't the way of successful people... The…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/453"}, {"id": 421, "slug": "first-421", "title": "Mana shu post kerak edi...", "fullTitle": "Mana shu post kerak edi...", "date": "2022-08-06", "lang": "uz", "tags": [], "body": "Aziz akani o&#39;quv markazlarida, xususiy maktablarida ishlash niyati ancha oldin paydo bo&#39;lgandi...<br><br>Lekin: ular Toshkentda va u yerga ishga kirish, jamoasiga qo&#39;shilish oson bo&#39;lmasligi aniq&#33;<br><br>IELTS dan 7.0 olganimdan keyin ko&#39;p joylardan ishga taklif qilishdi, ko&#39;plab o&#39;quv markazlardan, boshlang&#39;ich ta&#39;lim beradigan xususiy maktabdan va hattoki kuni kecha ochilish marosimi bo&#39;lgan Westen English School dan ham.<br><br>Hammasini rad qilgandim, sababi <u>birinchidan</u>: maqsadim shu joyda ishlab qolish emasdi, hozirgi darajamda qolib ketishni xohlamadim to&#39;g&#39;risi, o&#39;sish va rivojlanishga imkon bor joy kerak<br><u>Ikkinchidan</u>: man o&#39;zim o&#39;xshashni xohlagan inson(lar) oldiga borish, ular bilan fikr almashish, ularni yaqindan bilish va maksimal foyda &amp; maslahat olish istagi manda juda kuchli bo&#39;sa kerak.<br><br><i>Shunchunam avgust oyi oxirida Toshkentga ketyapman. Post uchun esa Aziz aka Rakhimovga respect :)</i>", "excerpt": "Aziz akani o'quv markazlarida, xususiy maktablarida ishlash niyati ancha oldin paydo bo'lgandi... Lekin: ular Toshkentda va u yerga ishga kirish…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/421"}, {"id": 419, "slug": "first-419", "title": "Uyg'on!", "fullTitle": "Uyg'on!", "date": "2022-08-05", "lang": "uz", "tags": [], "body": "Shuncha payt uxlaganing yetar...<br>Yoki yana uxlamoqchimisan?<br>Ho&#39;p, qachongacha???<br>Yana qancha vaqt senga berilgan umrni g&#39;aflatda o&#39;tkazmoqchisan-a?<br>Uyg&#39;on&#33;<br>Qalb ko&#39;zlaringni och&#33;<br><br><i>P.s: o&#39;zimdan o&#39;zimga aytilgan gaplar</i>", "excerpt": "Shuncha payt uxlaganing yetar... Yoki yana uxlamoqchimisan? Ho'p, qachongacha??? Yana qancha vaqt senga berilgan umrni g'aflatda o'tkazmoqchisan-a?…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/419"}, {"id": 416, "slug": "first-416", "title": "Foydasiz ishlar", "fullTitle": "Foydasiz ishlar", "date": "2022-07-31", "lang": "uz", "tags": [], "body": "Qanday ishlar bizga foydasiz ekanligini juda yaxshi bilamiz: o&#39;yin o&#39;ynash, ijtimoiy tarmoqlarda o&#39;tirish, soatlab telfonda gaplashish... <br><br>Foydasizligi aniq, ho&#39;p bunisini bilamiz.<br>Lekin zararli tomonlarini hech o&#39;ylab ko&#39;rganmisiz??? <br><br>Foydasiz ishlar o&#39;zi ko&#39;pincha zararli bo&#39;ladi&#33; Bizga hech qanday (na moddiy tarafdan, na ma&#39;naviy tarafdan) foyda keltirmaydigan ishlarni o&#39;zi shundog&#39;am qilmasligimiz kerakku&#33; Endi plus zarari ham bor bo&#39;lsachi? Umuman yaqinlashmasligimiz kerak, hatto soniya ham sarflash xato-da&#33;<br><br>Ho&#39;p bildik foydasiz ekan, ho&#39;p zarari ham borakan, lekin nima qilaylik? Bu ishlarni tark qilolmaymiz. <br><br>Inglizchada aytganda <i>addicted</i> bo&#39;lib qolgan insonlarda ( bu xuddi narkomaniya va alkagol mahsulotlariga o&#39;rganib qolishga o&#39;xshaydi) birdaniga to&#39;xtatish qiyin. Lekin yechimi bor&#33;&#33;&#33;<br><br>Qanday deysizmi?<br>- Ertaga aytaman🤫", "excerpt": "Qanday ishlar bizga foydasiz ekanligini juda yaxshi bilamiz: o'yin o'ynash, ijtimoiy tarmoqlarda o'tirish, soatlab telfonda gaplashish...…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/416"}, {"id": 415, "slug": "first-415", "title": "Vaqtim yo'q...", "fullTitle": "Vaqtim yo'q...", "date": "2022-07-30", "lang": "uz", "tags": [], "body": "Ko&#39;pchilik do&#39;stlarimiz, tanishlar bilan suhbatda &quot;...uni qilishim kerak, buni o&#39;qishim kerak...lekin vaqt yo&#39;q&quot; deganlarini eshitib qolamiz.<br><br>Manimcha muammo <b>vaqt ozligida emas&#33;</b> Sababi hammaga 1kunda 24soat vaqt beriladi. Muammo o&#39;sha vaqtni <b>qanday</b> o&#39;tkazishda&#33;<br><br>Qiladigan, qilmoqchi bo&#39;lgan ishlarimiz ko&#39;p, biroq qaysilari biz uchun eng muhimlari? Ya&#39;ni qaysilarini hozir qilmasak kelajakda(bir muddat o&#39;tib) qiynalamiz va ko&#39;plab muammolar kelib chiqadi???<br><br>Bizga 1tiyinlik foyda bermaydigan ishlardan voz kechaylik&#33; (bu haqida alohida post qilamiz nasib bo&#39;sa)<br><br><i>Prioritetni to&#39;g&#39;ri qo&#39;yvolishimiz kerak&#33;</i>", "excerpt": "Ko'pchilik do'stlarimiz, tanishlar bilan suhbatda \"...uni qilishim kerak, buni o'qishim kerak...lekin vaqt yo'q\" deganlarini eshitib qolamiz.…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/415"}, {"id": 395, "slug": "first-395", "title": "Mana bu inson mani shu darajaga chiqardi!", "fullTitle": "Mana bu inson mani shu darajaga chiqardi!", "date": "2022-06-16", "lang": "uz", "tags": [], "body": "Tanishing, bu <b>Bohodir aka Teshaboyev.</b> Ko&#39;pchilik <u>Mr. BAHA</u> sifatida yaxshi taniydi. Mani IELTS sayohatimni asosiy lideri bo&#39;ladilar. <br><br>3 oy pre-ielts kurslarida o&#39;qigan bo&#39;lsamda, shu vaqt ichida va kurs tugab gruppa tarqatilgandan kiyin ham hardoim qo&#39;llab quvvatlab, feedbacklar berib, maslahatini ayamagan inson&#33;<br><br>Man uchun shuncaki teacher yo ielts-instructor emaslar. Tug&#39;ishgan akamdek bo&#39;lib qolgan&#33;&#33;&#33; Alloh rozi bo&#39;lsin sizdan&#33;<br><br>Va ishonamanki man yolg&#39;iz emasman ya&#39;ni man kabi yuzlab yoshlar Bohodir akadan o&#39;zlariga kerakli bo&#39;lgan juda ko&#39;p narsalar o&#39;rganishgan&#33;<br><br><i>Alloh oilangizga totuvlik, ishlarizga baraka bersin akajon🙂🤲</i>", "excerpt": "Tanishing, bu Bohodir aka Teshaboyev. Ko'pchilik Mr. BAHA sifatida yaxshi taniydi. Mani IELTS sayohatimni asosiy lideri bo'ladilar. 3 oy pre-ielts…", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/395"}, {"id": 377, "slug": "first-377", "title": "Bahorning so'nggi kuni...", "fullTitle": "Bahorning so'nggi kuni...", "date": "2022-05-31", "lang": "uz", "tags": [], "body": "Yaqinda: bahor keldi, bahorning ilk kunlari dib quvonch ila yozilgan post-tabriklarni o&#39;qigandik va mana bugun esa Bahorning oxirgi kunida turibmiz...<br><br>Vaqt juda tez o&#39;tmoqda(mi) yoki bizga shunday tuyulmoqda(mi).<br><br>Balki ikkala variant ham to&#39;g&#39;ridur balki xato, lekin muhimi bu emas. Muhimi biz bundan qanday xulosa chiqarishimiz va kelayotgan yozni (va umrimizni qolgan qismini) mazmunli va foydali ishlar qilib o&#39;tkazishimiz&#33; <br><br><i>P.s: shu bahor faslida 3oy nimalar qildiz, nimalar qilomadiz? Keling kommentda bir suhbatlashamiz🙂</i>", "excerpt": "Yaqinda: bahor keldi, bahorning ilk kunlari dib quvonch ila yozilgan post-tabriklarni o'qigandik va mana bugun esa Bahorning oxirgi kunida…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/377"}, {"id": 299, "slug": "first-299", "title": "Katta maqsadlar emas ular haqida köp öylash va \"erishiladigan natija\"…", "fullTitle": "Katta maqsadlar emas ular haqida köp öylash va \"erishiladigan natija\" ni tasavvur qilish \"hozirgi moment\" da yashashdan tösishi va sizni qandaydur hotirjam va biroz dangasa qilib qöyishi mumkin!", "date": "2022-03-17", "lang": "uz", "tags": ["vada_qilingan_post"], "body": "Nega? Aslida maqsadlar va orzular haqida öylash yaxshi bölishi kerakmasmidi, mobodo? Aksincha bizga motivatsiya berib, bizni oldinga harakat qilishga undashi kerakmasmidi???<br><br>🤔🧐🤔🧐🤔<br><br>Birorta maqsadizga yetishganizda nima qilasiz? Özizni qanday his qilasiz? <br>- Odatda biz biror yutuqqa erishganimizda, xoh u kotta bösin, xoh kichik, &quot;yelkamizdan toğ ağdarilgandey böladi&quot;. Ana endi biroz dam olsak bölaveradi. Relax vaqti keldi... chunki biz nimagadur erishdik&#33;<br><br>Afsuski, biz hayoliy &quot;yutuqlar&quot; haqida öylaganimizdayam xuddi shunday xolat röy beradi. Maqsadlar sari qattiq harakat qilishni boshlash örniga, miyamiz allaqon u maqsadga erishib bölinganiga ishonadi, töğriroği &quot;aldanadi&quot;. <br><br>Bu borada köplab ilmiy tadqiqotlar olib borilgan...Bir necha izlanishlar shuni körsatadiki, shunday xolatlarda bizning tanamiz jismonan dam oladi. Va oxir oqibat qilishimiz kere bögan ishlarni qilishga &quot;xohish&quot; yöqoladi. Undanam yomoni: biz tasavvurimizda erishgan &quot;maqsad&quot;ga real hayotda umuman erisholmay qolishimiz ehtimoli ortadi...<br><br><b>Xösh, nima qilish kere unda?</b>🤔<br><br><b>Maqsadlarizga &quot;hayolan erishish&quot;ni va tasavvur qilishni töxtating&#33;&#33;&#33;</b><br>Uni örniga, shu maqsadga olib boruvchi &quot;process&quot; - jarayonni tasavvur qiling&#33;<br>Misol uchun: yaxshigina oylik tölanadigan ishda ishlayotganizi yoki shunaqangi ish örinlari tashkillab, biznes qilib yurganizi tasavvur qilishdan köra -&gt; u darajagacha chiqish uchun kerakli ilmlar örganiyotganizi, turli xil joylarga ish sörab arizalar yozib, intervyularga borib kelyotganizi yoki kimgadur shogird tushib, ustozizni ishlarini qilib, bilimlarini olib yurganizi tasavvur qiling&#33; <br><br>Boshqacharo misol: IELTS Band 9.0 olishizi tasavvur qilishni örniga -&gt; kursma-kurs öqib örganiyotganizi, inglizcha podcastlar eshitib, maqola va kitoblar öqiyotganizi, &quot;practice test&quot; lar qilyotganizi, &quot;mock&quot; imtihonlarga boryotganizi tasavvur qiling&#33;&#33;&#33;<br><br>Soddaroq misol: Olimpiada musobaqalarida yuqori örinda, oltin medal kötarib turganizi tasavvur qimengda; necha oylab, yillab shuğullanishiz, kuchli mehnat va tayorgarlik... shu jarayonlarni tasavvur qiling&#33;&#33;&#33;<br><br><b>&quot;Focus on the journey, not the destination.</b> <br>Joy is found not in finishing an activity but in doing it&quot; - Greg Johnson<br><br><i>Qisqa qilib aytganda: natijani emas, ungacha olib boradigan jarayonni tasavvur qiling&#33;&#33;&#33;</i><br><br>P.s: Yaqinda öqib tugatgan 2ta kitob asosida🙃 (17 Anti-Procrastination Hacks by Dominic Mann &amp; Declutter Your Mind by S.J.Scott and Barrie Davenport)", "excerpt": "Nega? Aslida maqsadlar va orzular haqida öylash yaxshi bölishi kerakmasmidi, mobodo? Aksincha bizga motivatsiya berib, bizni oldinga harakat qilishga…", "minutes": 2, "media": null, "url": "https://t.me/mrshokh_first/299"}, {"id": 297, "slug": "first-297", "title": "Qanday qilib \"Hozirgi Moment\"da yashash mumkin?", "fullTitle": "Qanday qilib \"Hozirgi Moment\"da yashash mumkin?", "date": "2022-03-15", "lang": "uz", "tags": ["vada_qilingan_post"], "body": "🤔🧐🤔<br><br>- <u>Òtmishni butunlay unutib bòlmaydi&#33;</u><br>Agar siz boshizi qattiq urib olgan, yoki qanaqadur kasal bòmasez òtmishni hech qachon esizdan chiqarolmesiz...<br><br>Esimizdan chiqarolmasek unda qanaqa qilib siz aytayotgan &quot;hozirgi moment&quot;da yashashimiz mumkin???<br>- Hop, hammaga gap focusda, ya&#39;ni e&#39;tiborda&#33; Focusni hozirgi hayotizga ko&#39;proq qaratish orqali òtmishdan uzulish mumkin&#33; Va buni birnechta yo&#39;llari bor:<br><br>• Avvalo, <b>fikrlash.</b> Qachonki òtmishdagi voqealar va erishaolmagan yutuqlar, kòngildagidek òtmagan suhbatlar... hamma-hammasini qancha òylamen, baribir foydasi yòqligini tushinib yetganizda, ular haqida bosh qotirme qòyasiz&#33;<br><br>• Ikkinchisi bu - <b>analiz(tahlil)</b><br>Sizni òtmish bilan boğlab, doimo siqilishizga sabab bòladigan qanday va qancha narsa(xotiralar) va insonlar bor?<br>Bunga sabab nima dib òylesiz? <br><br>• Va tahlildan sòng òz òzidan <b>Xulosalash va &quot;Tòğrilash&quot;</b><br>Sizni miyezi qotiradigan òtmishdagi voqea va xodisalarga sabablarni topganizdan keyin, kerakli xulosalar chiqarib olish eng muhimi. Hozirgi va kelajak hayotizda boshqa bunday holatlarga tushmaslik uchun albatta.<br>Qutulish uchun esa ularni tòğrilash kere&#33;<br>Kimdur bilan qaysidur suhbatta tortishib qolgan bòlsez, qachonlardur... va haligacha shu narsa haqida òylanib yurgan bòsez, qutulishni zòr yòli ösha inson bilan gaplashib vaziyatni tòğrilab olish...<br><br><b>• Voz kechish&#33;</b><br>Sizga hardoim òtmishdagi yoqimsiz vaziyatlar, ziddiyatlar... haqida eslatib asabga tegadigan insonlardan va narsalardan voz keching&#33; Tòğri biroz ğalati, lekin òtmishdan uzulib, hozirgi momentga kòproq e&#39;tibor berish uchun shunday qilish kerak&#33;&#33;&#33;<br><br><b>• Kelajakdagi buyuk maqsadlar</b><br>Muhimlik darajasida eng birinchilaridan aslida, sababi fikrlashiz òzgargan taqdirdayam, tahlil qilib xulosalar qilib, tòğrilaganizdayam, kimlardandur va yoki nimalardandur voz kechgan holatizdayam -&gt; agar sizi oldizda kelajak maqsadlariz, orzulariz bòmasa hozirgi momentda yashash hissini tuyolmasligiz mumkin&#33;<br><br><i>P.s: sizdayam qandaydur boshqacha usul bòsa, bemalol kommentariyada yozishingiz mumkin🙃</i>", "excerpt": "🤔🧐🤔 - Òtmishni butunlay unutib bòlmaydi! Agar siz boshizi qattiq urib olgan, yoki qanaqadur kasal bòmasez òtmishni hech qachon esizdan…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/297"}, {"id": 295, "slug": "first-295", "title": "Yana bir kun òtdi...", "fullTitle": "Yana bir kun òtdi...", "date": "2022-03-14", "lang": "uz", "tags": ["nimadur_ğalati"], "body": "Bugungi kuniz unçalik samarali òtmagan bòlishi mumkin, aytarli hich narsa qimagan bòlishiz mumkin, bular haqida umuman òylamayotgan bòlishizam  mumkin... <br>-&gt; lekin yaxshi xabar: sizda hali 6soatcha vaqt bor, bemalol òylab, nimalarga ulgurmaganiz, nimaga ulgurmaganizi òylash uchun...<br><br>• Ertaga kun bòyi bugungi kunizdegi voqealardi òylab yursez, deyarli hich narsa qimesiz yana, va yana xush xabar: kunni shu vaqtida sizda 6soat vaqt bòladi nimaga kun bòyi hichnima qimaganizi òylash haqida...<br><br><i>Hozirgi momentda yashashni òrganmagunizcha, shu xolat qaytarilaveradi...</i><br><br>P.s: <u>Eng qiziği:</u> òrganganizdan kiyinam, nimaga oldinroq òrganmaganiz haqida òylab qolishiz mumkin😅", "excerpt": "Bugungi kuniz unçalik samarali òtmagan bòlishi mumkin, aytarli hich narsa qimagan bòlishiz mumkin, bular haqida umuman òylamayotgan bòlishizam…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/295"}, {"id": 294, "slug": "first-294", "title": "Siqilmela, kayfiyatti kòtarila!", "fullTitle": "Siqilmela, kayfiyatti kòtarila!", "date": "2022-03-14", "lang": "uz", "tags": ["tonggi_motivatsiya"], "body": "Hali hammasi yaxshi bòladi... balki bugunmasdur, balki sizdamasdur... lekin qachondur bir kun kimdadur hammasi yaxshi bòpketadi&#33;&#33;&#33; <br><br>P.s: Ishanòring😅", "excerpt": "Hali hammasi yaxshi bòladi... balki bugunmasdur, balki sizdamasdur... lekin qachondur bir kun kimdadur hammasi yaxshi bòpketadi!!! P.s: Ishanòring😅", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/294"}, {"id": 290, "slug": "first-290", "title": "Yoshligimga qaytgim keladi...", "fullTitle": "Yoshligimga qaytgim keladi...", "date": "2022-03-08", "lang": "uz", "tags": [], "body": "Ehh, yoshligimizda (6-7yosh va kòpincha 3-sinfgacha) shunday tabriknomalar yasardik... <br><br>• Buvijonlarimizga, onajonlarimizga, kelinoyiyu ammajonlarimizga turli xil kòrinishlarda tabriknoma(откиритка) tayorlardik<br><br>• Xuddi Yangi Yilda rangli qoğozdan zanjirlar, gullar yasaganimizdek (xamirli kleydan yana😅)<br><br>• Toğri hali unchalik qarib qolganimiz yòq, lekin baribiram òsha davrlarni &quot;yoshligimiz...&quot; dib eslayveramiz hardoim.<br><br>• Hozirgi kunga kelib esa (ming afsuslar bòlsinkim) yaqinlarimizga telefon orqali sms yozib yokida Telegramdan tayyor bitta she&#39;riy tabrikni (hammaga òbshiy qilib) belgilab jònatib qòyyapmiz xolos...<br><br><i>Qòllarimiz bilan bezagan gulli, samimiy tilaklarga tòla tabriknomalarni berganimizdagi ularning quvonchini - sms yoki she&#39;riy tabrik xabarimizga javoban kelgan smaylik va stikerlar hech qachon òrnini bosolmaydi&#33;</i><br><br>Nima dimadilar?&#33; 🤔", "excerpt": "Ehh, yoshligimizda (6-7yosh va kòpincha 3-sinfgacha) shunday tabriknomalar yasardik... • Buvijonlarimizga, onajonlarimizga, kelinoyiyu…", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/290"}, {"id": 140, "slug": "first-140", "title": "\"Ingliz tilini bilmagan odam juda ham bechora odam, chunki u…", "fullTitle": "\"Ingliz tilini bilmagan odam juda ham bechora odam, chunki u odamlarni so'zlarini anglashda qiyinchiliklarga duch keladi\"-deyishadi...", "date": "2021-11-04", "lang": "uz", "tags": ["hayotiy_fikrlar"], "body": "Men aytamanki: &quot; Aslida Arab tilini bilmagan odam haqiqiy bechora odam, chunki u odamlar Robbisining so&#39;zini anglashda qiyinchilikka duch keladi&quot;<br><br>P.s: Qanchalar ham to&#39;g&#39;ri satrlar...<br>Kelajak kariyeramiz uchun ingliz tilini o&#39;rganibmizu, ammo bizlarni yaratgan, bizga risq-ro&#39;z bergan Robbimizning so&#39;zi bo&#39;lmish Qur&#39;oni Karimni o&#39;qish, anglash uchun arab tilini o&#39;rganmabmiz...<br><br><i>Boshlash uchun hech qachon kech emas, izlagan imkon topar deyishadiku, siz ham agar Arab tilini bilmasangiz, o&#39;rganishni boshlang&#33; </i><br>•<br>#hadis<br>Ibn Abbos (r.a) dan rivoyat qilingan hadisda aytiladiki:<br>Payg&#39;ambarimiz (s.a.v) aytdilar:<br>&quot;Arab tilini 3 sababga ko&#39;ra yaxshi ko&#39;ringlar&#33; Birinchisi, men arab bo&#39;lganim uchun. Ikkinchisi, Qur&#39;on arab tilida nozil bo&#39;lgani uchun. Va uchunchisi, Jannat tili arab tili bo&#39;lgani uchun&#33; - dedilar.", "excerpt": "Men aytamanki: \" Aslida Arab tilini bilmagan odam haqiqiy bechora odam, chunki u odamlar Robbisining so'zini anglashda qiyinchilikka duch keladi\"…", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/140"}, {"id": 132, "slug": "first-132", "title": "Ba'zida bariga shunchaki qo'l siltab ketvorging kelarkanuu...", "fullTitle": "Ba'zida bariga shunchaki qo'l siltab ketvorging kelarkanuu...", "date": "2021-10-31", "lang": "uz", "tags": ["for_myself", "self_motivated", "just_believe"], "body": "Ich-ichingda nimadur to&#39;xtatib qolarkan&#33;<br><br>Balki bu qalbing tubidagi <u>mehr-muhabbatdur...</u><br><br><i>Allohga bo&#39;lgan muhabbat...<br>Ota-onangga bo&#39;lgan muhabbat...<br>Yaqinlaringga bo&#39;lgan muhabbat...</i><br>                    ~~~<br>Balki bu qalbing tubidagi <u>ishonchdur...</u><br><br><i>Allohga bòlgan ishonch...<br>Kelajakka bòlgan ishonch...<br>O&#39;zingga bo&#39;lgan ishonch...</i><br>•<br><b>Ishon, hali hammmasi yaxshi bo&#39;ladi&#33;&#33;&#33;</b>", "excerpt": "Ich-ichingda nimadur to'xtatib qolarkan! Balki bu qalbing tubidagi mehr-muhabbatdur... Allohga bo'lgan muhabbat... Ota-onangga bo'lgan muhabbat...…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/132"}, {"id": 121, "slug": "first-121", "title": "Ba'zida shunchaki imkonsizlik va ilojsizlik to'qnash kelganda…", "fullTitle": "Ba'zida shunchaki imkonsizlik va ilojsizlik to'qnash kelganda, qalblar haqiqiy og'riqni his qilar ekan...", "date": "2021-10-28", "lang": "uz", "tags": ["hayotiy_fikrlar"], "body": "P.s: Bir inson ilojsizlikdan yordam so&#39;rasayu, sen imkonsizlikdan yordam berolmasang, manashu eng qiyin vaziyat ekan😔<br>•<br><i>Allohim hech kimni ilojsiz bir ahvolga solib qo&#39;ymasin va barchamizni sahovat va ehsonga qodir qilsin🤲</i>", "excerpt": "P.s: Bir inson ilojsizlikdan yordam so'rasayu, sen imkonsizlikdan yordam berolmasang, manashu eng qiyin vaziyat ekan😔 • Allohim hech kimni ilojsiz…", "minutes": 1, "media": null, "url": "https://t.me/mrshokh_first/121"}, {"id": 78, "slug": "first-78", "title": "Without social media ~ Life is better!", "fullTitle": "Without social media ~ Life is better!", "date": "2021-10-22", "lang": "uz", "tags": ["truth_of_life", "meaningful_quote", "social_media_detox"], "body": "Biroz tafakkur qilib, o&#39;zimizga chetdan nazar solsak, yuqori rakursdan qaraydigan bo&#39;lsak: Hayotimizni deyarli 1/3 qismi telefonda o&#39;tayotganiga guvoh bo&#39;lamiz😕<br><br><i>Buning sababi esa albatta ijtimoiy tarmoqlar...</i><br><br>To&#39;g&#39;ri, ko&#39;pchiligimiz ijtimoiy tarmoqlardan faqatgina aloqa vositasi yoki yaxshilik yo&#39;lida foydalanamiz. Uzoqdagi yaqinlarimiz bilan suhbatlashish, foydali ma&#39;lumotlar olish, ilm ahillarini kuzatish... shular jumlasidan.<br><br>Lekin tangani ikkinchi tomoni bo&#39;lganidek: mobil qurilmamiz foydamizdan ko&#39;ra ko&#39;proq zararimizga ishlamayaptimikin🤔 inglizchada <i><u>mental health</u></i> dgan narsa borda, o&#39;sha narsaga eng kòp ta&#39;sir qiladigan: mana shu biz ishlatayotgan telefonlar hisoblanadi&#33;<br><br>Nma deb o&#39;ylaysiz, ijtimoiy tarmoqdan foydalanmayotgan insonlar, biror joyi kamayib qomayaptimikin, kunlari o&#39;tyaptimikin ularniyam🧐🤔", "excerpt": "Biroz tafakkur qilib, o'zimizga chetdan nazar solsak, yuqori rakursdan qaraydigan bo'lsak: Hayotimizni deyarli 1/3 qismi telefonda o'tayotganiga…", "minutes": 1, "media": "photo", "url": "https://t.me/mrshokh_first/78"}, {"id": 45, "slug": "first-45", "title": "Agar suv gapira olganda edi…", "fullTitle": "Agar suv gapira olganda edi:", "date": "2021-10-16", "lang": "uz", "tags": [], "body": "Insonlarga qo&#39;lingizdan oldin - qalbingizni yuving deb aytgan bòlardi😕💦", "excerpt": "Insonlarga qo'lingizdan oldin - qalbingizni yuving deb aytgan bòlardi😕💦", "minutes": 1, "media": "video", "url": "https://t.me/mrshokh_first/45"}, {"id": 47, "slug": "first-47", "title": "Muhimi ishonch😉🔥", "fullTitle": "Muhimi ishonch😉🔥", "date": "2021-10-16", "lang": "uz", "tags": ["selfconfidence", "motivation", "believeinyourself"], "body": "Hech qachon o&#39;zingizga nisbatan shubhaga bormang. Siz barchasini uddalay olasiz. Shunchaki o&#39;zingizga ISHONING&#33;&#33;&#33;", "excerpt": "Hech qachon o'zingizga nisbatan shubhaga bormang. Siz barchasini uddalay olasiz. Shunchaki o'zingizga ISHONING!!!", "minutes": 1, "media": "video", "url": "https://t.me/mrshokh_first/47"}];
